item.command:
/bin/sh -lc "node <<'NODE'
const { chromium } = require('/workspace/.scotty/capture/node_modules/playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const outDir = '/workspace/.scotty/capture/artifacts';
  fs.mkdirSync(outDir, { recursive: true });
  const screenshotPath = path.join(outDir, 'counter-390x844.png');
  const videoDir = path.join(outDir, 'video');
  fs.rmSync(videoDir, { recursive: true, force: true });
  fs.mkdirSync(videoDir, { recursive: true });

  const browser = await chromium.launch({ headless: true });

  const shotContext = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  const shotPage = await shotContext.newPage();
  await shotPage.goto('http://localhost:5173', { waitUntil: 'networkidle' });
  await shotPage.screenshot({ path: screenshotPath, fullPage: false });
  await shotContext.close();

  const videoContext = await browser.newContext({
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 1,
    recordVideo: { dir: videoDir, size: { width: 390, height: 844 } }
  });
  const page = await videoContext.newPage();
  await page.goto('http://localhost:5173', { waitUntil: 'networkidle' });
  const button = page.locator('button').first();
  await button.waitFor({ state: 'visible', timeout: 5000 });
  const start = Date.now();
  while (Date.now() - start < 5000) {
    await button.click();
    await page.waitForTimeout(500);
  }
  const video = page.video();
  await videoContext.close();
  await browser.close();

  const rawVideoPath = await video.path();
  const finalVideoPath = path.join(outDir, 'counter-clicks-5s.webm');
  fs.copyFileSync(rawVideoPath, finalVideoPath);

  console.log("'`screenshot=${screenshotPath}`);
  console.log(`video=${finalVideoPath}`);
})();
NODE'

